import {readCart} from './pf-cart.mjs';
import {loadFile} from './storage.mjs';
import {renderCartMockup} from './cart-mockup.mjs';
const node=(tag,text,className)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(className)n.className=className;return n;};
async function artworkUploads(line){const ids=[...new Set(line.decorations.flatMap(d=>d.artworks.map(art=>art.logo.id)))],uploads=[];for(const id of ids){const file=await loadFile(id);if(!file)throw Error('En original trykfil mangler i browseren. Åbn designet og upload den igen.');const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));uploads.push({id,base64:btoa(binary)});}return uploads;}
export async function renderCompanies(root,api){
 root.replaceChildren();const intro=node('section',undefined,'panel'),heading=node('h2','Virksomheder og faste designs'),instructions=node('p','Design et produkt i webshoppen og læg det i din kurv. Gem det her til en virksomhed. Originalfilerne kopieres til serveren; kunden vælger efterfølgende kun størrelser og antal. PF-korrektur og betalingskontrol følger det almindelige ordreflow.');
 const browse=node('a','Design nyt produkt →','action');browse.href='/produkter';browse.target='_blank';browse.rel='noopener';
 const label=node('label','Virksomhed','company-admin-picker'),select=node('select');select.setAttribute('aria-label','Vælg virksomhed');label.append(select);intro.append(heading,instructions,browse,label);root.append(intro);
 const workspace=node('div');root.append(workspace);
 try{const accounts=await (await api('/api/admin/companies')).json();for(const account of accounts){const option=node('option',account.name);option.value=account.id;select.append(option);}if(!accounts.length){workspace.append(node('p','Der er endnu ingen virksomhedskonti.'));return;}
 async function refresh(){workspace.replaceChildren();const companyId=select.value,list=node('section',undefined,'panel'),message=node('p','', 'muted');list.append(node('h2','Virksomhedens sortiment'));workspace.append(list);
 try{const account=accounts.find(a=>a.id===companyId),settings=node('details',undefined,'panel'),summary=node('summary','Loginoplysninger'),form=node('form'),userLabel=node('label','Brugernavn'),user=node('input'),passwordLabel=node('label','Ny adgangskode'),password=node('input'),accountStatus=node('p');user.className=password.className='company-admin-name';user.value=account.username;user.name='companyUsername';user.autocomplete='off';password.type='password';password.name='companyPassword';password.autocomplete='new-password';password.minLength=8;password.maxLength=200;user.required=password.required=true;userLabel.append(user);passwordLabel.append(password);const accountSave=node('button','Gem login privat på serveren','action');accountSave.type='submit';accountStatus.setAttribute('role','status');form.append(node('p',account.configured?'Virksomhedens login er aktiveret. Gem kun her, hvis det skal ændres.':'Aktivér virksomhedens login her. Oplysningerne gemmes privat på serveren og kommer ikke i GitHub.'),userLabel,passwordLabel,accountSave,accountStatus);form.onsubmit=async event=>{event.preventDefault();accountSave.disabled=true;accountStatus.textContent='Gemmer …';try{const updated=await (await api(`/api/admin/companies/${companyId}/account`,'POST',{username:user.value,password:password.value})).json();account.configured=updated.configured;account.username=updated.username;accountStatus.textContent='Login er aktiveret og gemt privat på serveren.';}catch(error){accountStatus.textContent=error.message;}finally{password.value='';accountSave.disabled=false;}};settings.append(summary,form);if(!account.configured)settings.open=true;workspace.prepend(settings);const products=await (await api(`/api/admin/companies/${companyId}/products`)).json();if(!products.length)list.append(node('p','Ingen faste produkter endnu.'));for(const item of products){const row=node('div',undefined,'order-card'),info=node('div');info.append(node('strong',item.name),node('p',item.variants.map(v=>v.size).join(' · ')),node('small',item.files.map(f=>f.name).join(', ')));const remove=node('button','Fjern fra sortiment','action light');remove.onclick=async()=>{remove.disabled=true;try{await api(`/api/admin/companies/${companyId}/products/${item.id}`,'POST',{});await refresh();}catch(error){message.textContent=error.message;remove.disabled=false;}};row.append(info,remove);list.append(row);}list.append(message);
 const drafts=node('section',undefined,'panel');drafts.append(node('h2','Gem design fra din kurv'));workspace.append(drafts);const lines=readCart().filter(l=>!l.companyTemplate&&l.decorations?.length);if(!lines.length)drafts.append(node('p','Din kurv indeholder ingen færdige designs. Design et produkt først, og tryk derefter Opdatér i administrationen.'));
 const seen=new Set();for(const line of lines){const key=line.productId+':'+line.sku;if(seen.has(key))continue;seen.add(key);const row=node('div',undefined,'order-card'),info=node('div'),name=node('input');name.className='company-admin-name';name.placeholder='Navn på virksomhedens produkt';name.setAttribute('aria-label','Navn på virksomhedens produkt');name.maxLength=200;const edit=node('a','Åbn design →');edit.href=`/design/${line.productId}?cart=${encodeURIComponent(line.id)}`;edit.target='_blank';edit.rel='noopener';const status=node('p','');status.setAttribute('role','status');info.append(node('strong',line.productId+' · '+line.sku),node('p',line.decorations.map(d=>`${d.position} · ${d.method}`).join(' / ')),name,edit,status);const save=node('button','Gem til virksomheden','action');save.onclick=async()=>{const targetCompany=companyId;save.disabled=true;status.textContent='Kontrollerer design og gemmer originalfiler …';try{const response=await fetch('/api/pf-product/'+line.productId);if(!response.ok)throw Error('Produktet kunne ikke hentes.');const product=await response.json(),variant=product.variants.find(v=>v.sku===line.sku),previews=[];for(const d of line.decorations){const option=variant?.options.find(o=>o.id===d.optionId);if(!option)throw Error('Trykplaceringen findes ikke længere.');const canvas=await renderCartMockup(product,option,d);previews.push(canvas.toDataURL('image/png').split(',')[1]);}await api(`/api/admin/companies/${targetCompany}/products`,'POST',{name:name.value||product.name,line,artworks:await artworkUploads(line),previews});await refresh();}catch(error){status.textContent=error.message;save.disabled=false;}};row.append(info,save);drafts.append(row);}
 }catch(error){message.textContent=error.message;list.append(message);}}
 select.onchange=refresh;await refresh();
 }catch(error){workspace.append(node('p',error.message));}
}
